import itertools, sys

def is_sat(num_vars, clauses):
    for assign in itertools.product([0,1], repeat=num_vars):
        ok=True
        for c in clauses:
            cnt=sum(assign[v-1] for v in c)
            if cnt!=1:
                ok=False; break
        if ok:
            return True
    return False

for n in range(3,6):
    vars=list(range(1,n+1))
    all_clauses=[list(c) for c in itertools.combinations(vars,3)]
    # try combinations of up to 3 clauses
    for r in range(1,4):
        for combo in itertools.combinations(all_clauses, r):
            if not is_sat(n, combo):
                print('found', n, combo)
                sys.exit()
print('none found')
PY"}

